def _ensure_package(name: str) -> _bundle_types.ModuleType:
    existing = _bundle_sys.modules.get(name)
    if existing is not None:
        return existing
    module = _bundle_types.ModuleType(name)
    module.__file__ = _BUNDLE_FILE
    module.__package__ = name.rpartition(".")[0]
    module.__path__ = []  # type: ignore[attr-defined]
    _bundle_sys.modules[name] = module
    if "." in name:
        parent_name, child = name.rsplit(".", 1)
        parent = _ensure_package(parent_name)
        setattr(parent, child, module)
    return module


def _load_bundled_module(name: str, *, package: bool = False) -> _bundle_types.ModuleType:
    raw = _BUNDLED_MODULES[name]
    source = _bundle_zlib.decompress(_bundle_base64.b85decode(raw.encode("ascii"))).decode("utf-8")
    if package:
        module = _ensure_package(name)
    else:
        if "." in name:
            parent_name, child = name.rsplit(".", 1)
            parent = _ensure_package(parent_name)
        else:
            parent = None
            child = name
        module = _bundle_types.ModuleType(name)
        module.__file__ = _BUNDLE_FILE
        module.__package__ = name.rpartition(".")[0]
        _bundle_sys.modules[name] = module
        if parent is not None:
            setattr(parent, child, module)
    exec(compile(source, f"{_BUNDLE_FILE}::{name}", "exec"), module.__dict__)
    return module


# Embedded support modules required by memory/archive profiles.
_ensure_package("latka_jazn")
_ensure_package("latka_jazn.memory")
_ensure_package("latka_jazn.packaging")
_ensure_package("latka_jazn.archive")
_load_bundled_module("latka_jazn.memory.storage_limits")
_load_bundled_module("latka_jazn.packaging.memory_raw_segmentation")
_load_bundled_module("latka_jazn.archive.service")
_load_bundled_module("latka_jazn.archive.hardened_service")
_load_bundled_module("latka_jazn.archive", package=True)

# Historical generator layers, now internal to this single physical file.
_ensure_package("tools")
_load_bundled_module("tools._jazn_pack_generator_core")
_load_bundled_module("tools._jazn_pack_generator_memory_v2")
_load_bundled_module("tools._jazn_pack_generator_v1601_policy")
_load_bundled_module("tools._jazn_pack_generator_v1638_archive_io")
_load_bundled_module("tools._jazn_pack_generator_v16311_profiles")

_impl: Any = _load_bundled_module("tools._jazn_pack_generator_memory_v2")
_apply_v1601_policy: Any = getattr(
    _load_bundled_module("tools._jazn_pack_generator_v1601_policy"), "apply"
)
_apply_v1638_archive_io: Any = getattr(
    _load_bundled_module("tools._jazn_pack_generator_v1638_archive_io"), "apply"
)
_apply_v16311_profiles: Any = getattr(
    _load_bundled_module("tools._jazn_pack_generator_v16311_profiles"), "apply"
)

_apply_v1601_policy(_impl)
_apply_v1638_archive_io(_impl)
_apply_v16311_profiles(_impl)

# Make reports/settings point to this public two-file entrypoint.
_impl.__file__ = __file__
_core = getattr(_impl, "_core", None)
if _core is not None:
    _core.__file__ = __file__

for _name, _value in vars(_impl).items():
    if _name not in {"__name__", "__loader__", "__package__", "__spec__", "__file__"}:
        globals()[_name] = _value

GENERATOR_VERSION = "8.6"
SETTINGS_SCHEMA = "jazn_pack_generator_settings/v8.6"


def __getattr__(name: str) -> Any:
    if hasattr(_impl, name):
        return getattr(_impl, name)
    core = getattr(_impl, "_core", None)
    if core is not None and hasattr(core, name):
        return getattr(core, name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")


class _GeneratorPublicModule(_bundle_types.ModuleType):
    """Forward monkeypatches through both implementation layers."""

    def __setattr__(self, name: str, value: Any) -> None:
        super().__setattr__(name, value)
        impl = self.__dict__.get("_impl")
        if impl is None or name == "_impl":
            return
        if hasattr(impl, name):
            setattr(impl, name, value)
        core = getattr(impl, "_core", None)
        if core is not None and hasattr(core, name):
            setattr(core, name, value)


_current_module = _bundle_sys.modules.get(__name__)
if _current_module is not None and not isinstance(_current_module, _GeneratorPublicModule):
    _current_module.__class__ = _GeneratorPublicModule


def main(argv: Sequence[str] | None = None) -> int:
    return int(_impl.main(argv))


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        print(_impl._paint("\nPrzerwano przez użytkownika.", _impl.ANSI_YELLOW, stream=_bundle_sys.stderr), file=_bundle_sys.stderr)
        raise SystemExit(130)
    except _impl.PackError as exc:
        print(_impl._paint(f"BŁĄD: {exc}", _impl.ANSI_RED, _impl.ANSI_BOLD, stream=_bundle_sys.stderr), file=_bundle_sys.stderr)
        raise SystemExit(2)
